<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

/** Installs only a newly named database. The existing application is never targeted. */
final class Deployment {
 static function sqlSupported(string $version):bool {preg_match_all('/[0-9]+\.[0-9]+\.[0-9]+/',$version,$matches);$parts=$matches[0];$maria=str_contains(strtolower($version),'mariadb');$number=$parts[0]??null;if($maria&&$number==='5.5.5'&&isset($parts[1]))$number=$parts[1];return $number!==null&&version_compare($number,$maria?'10.3.0':'8.0.16','>=');}
 static function health(\PDO $db,array $actor):array {permit($actor,'admin');$started=microtime(true);$version=query($db,'SELECT VERSION()')->fetchColumn();$connectionMs=round((microtime(true)-$started)*1000,2);$started=microtime(true);$report=Reports::report($db,[]);$reportMs=round((microtime(true)-$started)*1000,2);$backup=config()['backup_directory']??storage().'/backups';$grants=query($db,'SHOW GRANTS')->fetchAll(\PDO::FETCH_COLUMN);$ddl=false;foreach($grants as $grant)if(preg_match('/\b(?:ALL PRIVILEGES|CREATE|ALTER|DROP)\b/i',$grant))$ddl=true;return ['requirements'=>self::requirements(),'environment'=>config()['environment'],'database_version'=>$version,'sql_connection_ms'=>$connectionMs,'report_ms'=>$reportMs,'active_invoices'=>$report['total'],'backup_writable'=>is_dir($backup)&&is_writable($backup),'backup_outside_web'=>self::outsideWeb($backup),'https'=>https(),'runtime_without_ddl'=>!$ddl,'version'=>config()['version']??'local'];}
 static function requirements():array {
  $out=['php'=>PHP_VERSION,'php_supported'=>PHP_VERSION_ID>=80200];foreach(['pdo_mysql','mbstring','zip','dom','zlib'] as $ext)$out[$ext]=extension_loaded($ext);
  $dir=storage();$out['data_writable']=is_dir($dir)&&is_writable($dir);$out['data_outside_web']=self::outsideWeb($dir);return $out;
 }
 static function outsideWeb(string $dir):bool {
  $real=realpath($dir);if(!$real)return false;$web=realpath(($_SERVER['DOCUMENT_ROOT']??'')?:dirname(__DIR__));if(!$web)return false;$a=str_replace('\\','/',$real);$b=rtrim(str_replace('\\','/',$web),'/');if(preg_match('~^/volume[0-9]+/(?:web|web_packages)(?:/|$)~',$a))return false;if(DIRECTORY_SEPARATOR==='\\'){$a=strtolower($a);$b=strtolower($b);}return $a!==$b&&!str_starts_with($a,$b.'/');
 }
 static function tokenValid(string $token):bool {$file=storage().'/setup-token.sha256';return strlen($token)>=32&&is_file($file)&&hash_equals(trim(file_get_contents($file)),hash('sha256',$token));}
 static function restoreChoices():array {$dir=storage().'/restore';$out=[];foreach([...(glob($dir.'/*.json.gz')?:[]),...(glob($dir.'/*.jsonl.gz')?:[])] as $f){if(is_file($f.'.meta.json'))$out[]=basename($f);}sort($out);return $out;}
 static function backupPath(string $name):string {if($name!==basename($name)||!preg_match('/^[A-Za-z0-9_.-]+\.jsonl?\.gz$/D',$name))throw new Problem('Nume de backup invalid.');$f=storage().'/restore/'.$name;if(!is_file($f)||!is_file($f.'.meta.json'))throw new Problem('Backupul și metadata trebuie copiate în directorul privat restore.');return $f;}
 static function preflightBackup(string $file,string $username):void {
  if(str_ends_with($file,'.json.gz')){[$data]=self::readBackup($file);foreach($data['tables']['users']??[] as $u)if($u['username']===$username)throw new Problem('Numele administratorului există deja în backup. Alege un nume nou pentru contul de instalare.');return;}
  $meta=json_decode(file_get_contents($file.'.meta.json'),true,512,JSON_THROW_ON_ERROR);if(!hash_equals((string)($meta['sha256']??''),hash_file('sha256',$file)))throw new Problem('Backupul istoric are hash invalid.');$f=gzopen($file,'rb');try{$header=json_decode(gzgets($f),true,512,JSON_THROW_ON_ERROR);if(($header['format']??'')!=='plati-goldendrinks-1')throw new Problem('Format istoric necunoscut.');$counts=[];while(($line=gzgets($f))!==false){$r=json_decode($line,true,512,JSON_THROW_ON_ERROR);$counts[$r['table']]=($counts[$r['table']]??0)+1;if($r['table']==='app_users'&&$r['row']['username']===$username)throw new Problem('Administratorul există deja în backup. Alege un nume nou.');}foreach($meta['rows']??[] as $table=>$n)if(($counts[$table]??0)!==$n)throw new Problem('Backup istoric incomplet.');}finally{gzclose($f);}
 }
 static function connect(array $v,?string $database=null):\PDO {if(!preg_match('/^[a-zA-Z0-9_.:-]+$/D',(string)$v['host'])||(int)$v['port']<1||(int)$v['port']>65535)throw new Problem('Gazdă sau port SQL invalid.');$dsn='mysql:host='.$v['host'].';port='.(int)$v['port'].($database!==null?';dbname='.$database:'').';charset=utf8mb4';return new \PDO($dsn,$v['user'],$v['password'],[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION,\PDO::ATTR_DEFAULT_FETCH_MODE=>\PDO::FETCH_ASSOC,\PDO::ATTR_EMULATE_PREPARES=>false]);}
 static function applySchema(\PDO $db):void {$schema=require __DIR__.'/schema.php';foreach(explode(';',preg_replace('/^--.*$/m','',$schema)) as $sql)if(trim($sql)!=='')$db->exec($sql);}
 static function grantRuntime(\PDO $server,\PDO $db,string $database,string $account):void {if(!preg_match('/^pg_plati_[a-f0-9]{8}$/D',$database))throw new Problem('Bază runtime invalidă.');foreach(query($db,'SHOW TABLES')->fetchAll(\PDO::FETCH_COLUMN) as $table){if(!preg_match('/^[a-z_]+$/D',$table))throw new Problem('Tabel runtime invalid.');$server->exec('GRANT SELECT,INSERT,UPDATE,DELETE ON '.$database.'.'.$table.' TO '.$account);}}
 static function readBackup(string $file):array {
  $meta=json_decode(file_get_contents($file.'.meta.json'),true,512,JSON_THROW_ON_ERROR);if(!hash_equals((string)($meta['sha256']??''),hash_file('sha256',$file)))throw new Problem('Hashul backupului nu corespunde.');$raw=gzdecode(file_get_contents($file));if($raw===false)throw new Problem('Backup comprimat invalid.');$data=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(($data['format']??'')!=='plati-rebuild-1'||!isset($data['tables'])||!is_array($data['tables']))throw new Problem('Folosește backupul complet al aplicației reconstruite.');$paths=Backups::verifyArchives($file,$meta);if(count($paths)!==count($data['tables']['import_files']??[]))throw new Problem('Backup incomplet: lipsesc fișierele originale importate.');return [$data,$meta,$paths];
 }
 static function restoreIntoEmpty(\PDO $db,string $file):array {
  [$data,$meta,$paths]=self::readBackup($file);$tables=query($db,'SHOW TABLES')->fetchAll(\PDO::FETCH_COLUMN);$actual=$tables;$expected=array_keys($data['tables']);sort($actual);sort($expected);if($actual!==$expected)throw new Problem('Schema backupului diferă de versiunea instalată.');
  $allowed=[];foreach($tables as $table){if(!preg_match('/^[a-z_]+$/D',$table))throw new Problem('Tabel invalid.');if((int)query($db,'SELECT COUNT(*) FROM `'.$table.'`')->fetchColumn()!==0)throw new Problem('Restaurarea cere o bază complet goală.');$allowed[$table]=query($db,'SHOW COLUMNS FROM `'.$table.'`')->fetchAll(\PDO::FETCH_COLUMN);}
  // Every table/column identifier is checked against the freshly created schema.
  foreach($data['tables'] as $table=>$rows)foreach($rows as $row){$cols=array_keys($row);$target=$allowed[$table];sort($cols);sort($target);if($cols!==$target)throw new Problem('Coloanele backupului diferă: '.$table);}
  $db->exec('SET FOREIGN_KEY_CHECKS=0');try{transaction($db,function()use($db,$data){foreach($data['tables'] as $table=>$rows)foreach($rows as $row)query($db,'INSERT INTO `'.$table.'`(`'.implode('`,`',array_keys($row)).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')',array_values($row));});}finally{$db->exec('SET FOREIGN_KEY_CHECKS=1');}
  $verified=Backups::verifyRestored($db,$data['tables']);$uploads=storage().'/uploads';if(!is_dir($uploads)&&!mkdir($uploads,0700,true))throw new Problem('Directorul pentru surse nu poate fi creat.');
  foreach($paths as $id=>$source){$target=$uploads.'/'.basename($source);if(!is_file($target)&&!copy($source,$target))throw new Problem('Arhiva sursă nu poate fi copiată.');if(!hash_equals(hash_file('sha256',$source),hash_file('sha256',$target)))throw new Problem('Arhiva sursă copiată diferă.');if(is_file($source.'.meta.json')&&!copy($source.'.meta.json',$target.'.meta.json'))throw new Problem('Metadata nu poate fi copiată.');query($db,'UPDATE import_files SET private_archive_reference=? WHERE id=?',[$target,$id]);}
  return ['tables'=>count($tables),'foreign_keys'=>$verified['foreign_keys_checked'],'archives'=>count($paths),'snapshot_created'=>$data['created_at']??null,'snapshot_sha256'=>$meta['sha256']];
 }
 static function install(array $v):array {
  if(is_file(storage().'/config.php'))throw new Problem('Instalarea există deja.',409);if(!self::tokenValid((string)($v['token']??'')))throw new Problem('Cod de instalare invalid.',403);
  $r=self::requirements();foreach($r as $key=>$value)if($key!=='php'&&$value!==true)throw new Problem('Verificare de mediu nereușită: '.$key);
  $environment=$v['environment']??'staging';if(!in_array($environment,['staging','production'],true))throw new Problem('Mediu invalid.');$database=trim((string)($v['database']??''));if(!preg_match('/^pg_plati_[a-f0-9]{8}$/D',$database))throw new Problem('Baza nouă trebuie să aibă forma pg_plati_ urmată de 8 caractere hexazecimale.');
  $username=trim((string)($v['admin_username']??''));$display=trim((string)($v['admin_name']??''));$password=(string)($v['admin_password']??'');if(!preg_match('/^[\pL0-9_.-]{3,100}$/uD',$username)||$username==='preview_admin'||mb_strlen($display)<2||strlen($password)<12)throw new Problem('Date administrator invalide; parola cere minimum 12 caractere.');
  if($environment==='production'&&PHP_SAPI!=='cli'&&!https())throw new Problem('Instalarea pentru producție cere HTTPS. Poți folosi mediul de verificare pe o adresă separată.');
  $backupName=(string)($v['backup']??'');$backup=$backupName!==''?self::backupPath($backupName):null;if(!$backup&&($v['empty_confirmed']??'')!=='1')throw new Problem('Alege backupul sau confirmă explicit instalarea fără date.');if($backup)self::preflightBackup($backup,$username);
  $backupDir=trim((string)($v['backup_directory']??''));if($backupDir==='')$backupDir=storage().'/backups';if(!is_dir($backupDir)||!is_writable($backupDir)||!self::outsideWeb($backupDir))throw new Problem('Directorul backup trebuie să existe, să permită scrierea PHP și să fie în afara zonei web.');$probe=$backupDir.'/.plati-write-'.bin2hex(random_bytes(8));if(file_put_contents($probe,'ok',LOCK_EX)!==2)throw new Problem('PHP nu poate scrie backupurile.');unlink($probe);
  $lock=fopen(storage().'/installation.lock','c+');if(!$lock||!flock($lock,LOCK_EX|LOCK_NB))throw new Problem('O instalare este deja în curs.',409);
  $created=false;$accountCreated=false;$runtimeUser='plati_'.bin2hex(random_bytes(6));$runtimePassword='Pg!aA9#'.bin2hex(random_bytes(24));try{if(is_file(storage().'/config.php'))throw new Problem('Instalarea a fost deja încheiată.',409);$server=self::connect($v);$sqlVersion=(string)query($server,'SELECT VERSION()')->fetchColumn();if(!self::sqlSupported($sqlVersion))throw new Problem('Este necesar MariaDB 10.3+ sau MySQL 8.0.16+.');$exists=(int)query($server,'SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=?',[$database])->fetchColumn();if($exists)throw new Problem('Baza există deja. Alege un nume nou; nu suprascriem tabele existente.');$server->exec('CREATE DATABASE `'.$database.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');$created=true;$db=self::connect($v,$database);self::applySchema($db);
   if($backup&&str_ends_with($backup,'.jsonl.gz')){if(!is_dir(storage().'/uploads'))mkdir(storage().'/uploads',0700,true);$archive=storage().'/uploads/'.hash_file('sha256',$backup).'.jsonl.gz';if(!copy($backup,$archive)||!copy($backup.'.meta.json',$archive.'.meta.json'))throw new Problem('Snapshotul istoric nu poate fi arhivat.');$migration=Migration::run($db,$archive)+Migration::verifySnapshot($db,$archive);}else $migration=$backup?self::restoreIntoEmpty($db,$backup):['tables'=>0,'archives'=>0];
   if(one($db,'SELECT id FROM users WHERE username=?',[$username]))throw new Problem('Numele de administrator există în backup. Alege un nume nou; contul vechi nu va fi suprascris.');
   query($db,'INSERT INTO users(username,password_hash,display_name,role,enabled) VALUES(?,?,?,\'admin\',1)',[$username,password_hash($password,PASSWORD_DEFAULT),$display]);$id=(int)$db->lastInsertId();query($db,"UPDATE users SET enabled=0,password_hash=? WHERE username='preview_admin'",[password_hash(bin2hex(random_bytes(40)),PASSWORD_DEFAULT)]);
   $account=$server->quote($runtimeUser).'@'.$server->quote('localhost');$server->exec('CREATE USER '.$account.' IDENTIFIED BY '.$server->quote($runtimePassword));$accountCreated=true;self::grantRuntime($server,$db,$database,$account);$configuration=['environment'=>$environment,'host'=>$v['host'],'port'=>(int)$v['port'],'database'=>$database,'user'=>$runtimeUser,'password'=>$runtimePassword,'backup_directory'=>$backupDir,'require_https'=>$environment==='production','installed_at'=>gmdate('c'),'version'=>'release-2026.11.02'];$runtime=self::connect($configuration,$database);query($runtime,'SELECT COUNT(*) FROM users')->fetchColumn();$temp=storage().'/config-'.bin2hex(random_bytes(8)).'.tmp';if(file_put_contents($temp,"<?php\nreturn ".var_export($configuration,true).";\n",LOCK_EX)===false)throw new Problem('Configurarea nu poate fi scrisă.');chmod($temp,0600);if(!rename($temp,storage().'/config.php'))throw new Problem('Configurarea nu poate fi activată.');audit($db,'installation_completed',['environment'=>$environment,'migration'=>$migration],['id'=>$id]);file_put_contents(storage().'/installation-receipt.json',json(['database'=>$database,'environment'=>$environment,'created_at'=>gmdate('c'),'migration'=>$migration]),LOCK_EX);rename(storage().'/setup-token.sha256',storage().'/setup-token.used');return ['installed'=>true,'migration'=>$migration];
  }catch(\Throwable $e){if($created&&!is_file(storage().'/config.php')){try{$server->exec('DROP DATABASE `'.$database.'`');if($accountCreated)$server->exec('DROP USER '.$server->quote($runtimeUser).'@'.$server->quote('localhost'));}catch(\Throwable $cleanup){error_log('PLATI: failed installation database requires manual cleanup: '.$database);}}throw $e;}finally{flock($lock,LOCK_UN);fclose($lock);}
 }
